using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using SupermarketCatalog.Data;using SupermarketCatalog.Models;
namespace SupermarketCatalog.Pages.Admin;
[Authorize]public class NewModel(AppDbContext db,UserManager<StoreUser> users):PageModel{[BindProperty]public Deal Deal{get;set;}=new(){ExpiresAt=DateTime.UtcNow.AddDays(7)};[BindProperty]public IFormFile? ImageFile{get;set;}public string Lang=>Request.Query["lang"].FirstOrDefault()??"ku";public string Dir=>Lang=="en"?"ltr":"rtl";public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid)return Page();var u=await users.GetUserAsync(User);if(u is null)return Challenge();var store=await db.Stores.SingleOrDefaultAsync(x=>x.OwnerId==u.Id);if(store is null)return BadRequest("Store profile not found");if(u.ActiveDealsCount>=u.MonthlyDealLimit)return BadRequest("Deal limit reached");if(ImageFile is not null){if(ImageFile.Length>5*1024*1024||!new[]{"image/jpeg","image/png","image/webp"}.Contains(ImageFile.ContentType))return BadRequest("Invalid image");var dir=Path.Combine(Directory.GetCurrentDirectory(),"wwwroot/uploads");Directory.CreateDirectory(dir);var ext=Path.GetExtension(ImageFile.FileName).ToLowerInvariant();var name=$"{Guid.NewGuid():N}{ext}";await using var stream=System.IO.File.Create(Path.Combine(dir,name));await ImageFile.CopyToAsync(stream);Deal.ImageUrl=$"/uploads/{name}";}if(string.IsNullOrWhiteSpace(Deal.ImageUrl))return BadRequest("Image is required");Deal.StoreId=store.Id;db.Deals.Add(Deal);u.ActiveDealsCount++;await db.SaveChangesAsync();return RedirectToPage("Index");}}